// Register-row nodes: small, closed-form Grasshopper components (Maths > Operators / Util / Trig,
// Sets > List / Sequence / Text) added one Register row at a time. Every node here has a hand-computed
// oracle in dino8-app/tests/sections/94_fr*.sh (generated by tests/flowrows_gen.py): the closed form is
// written next to the expected value there, never derived from this code.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <numeric>
#include <string>
#include <vector>

#include "flow/FlowGraph.h"

namespace dino8::flow {

namespace {

PortDef In(std::string name, Kind k, Access acc = Access::Item, Value def = Value::Null(), bool optional = false) {
  PortDef p; p.name = name; p.nick = name; p.kind = k; p.access = acc; p.def = std::move(def); p.optional = optional; return p;
}
PortDef Out(std::string name, Kind k) { PortDef p; p.name = name; p.nick = name; p.kind = k; return p; }

// The finite numbers of a list, in order (non-numeric items are skipped).
std::vector<double> Numbers(const std::vector<Value>& l) {
  std::vector<double> out;
  for (const Value& v : l) { double x; if (v.AsNumber(x)) out.push_back(x); }
  return out;
}

// Splits UTF-8 text into code points so a non-ASCII letter counts as one edit, not several.
std::vector<std::uint32_t> CodePoints(const std::string& s) {
  std::vector<std::uint32_t> out;
  for (size_t i = 0; i < s.size();) {
    const unsigned char c = static_cast<unsigned char>(s[i]);
    size_t len = c < 0x80 ? 1 : (c >> 5) == 0x6 ? 2 : (c >> 4) == 0xE ? 3 : (c >> 3) == 0x1E ? 4 : 1;
    if (i + len > s.size()) len = 1;
    std::uint32_t cp = len == 1 ? c : (c & (0xFFu >> (len + 1)));
    for (size_t k = 1; k < len; ++k) cp = (cp << 6) | (static_cast<unsigned char>(s[i + k]) & 0x3Fu);
    out.push_back(cp);
    i += len;
  }
  return out;
}

std::uint32_t FoldCase(std::uint32_t c) { return (c >= 'A' && c <= 'Z') ? c + 32 : c; }

void AddRowMaths() {
  Registry& r = Registry::Get();
  {
    NodeDef d; d.name = "Factorial"; d.nick = "Fact"; d.category = "Maths"; d.subcategory = "Operators";
    d.description = "n factorial. Exact up to 20!; larger results are rounded to the nearest double and flagged.";
    d.inputs = {In("N", Kind::Integer, Access::Item, Value::Integer(5))};
    d.outputs = {Out("Factorial", Kind::Number)};
    d.eval = [](EvalContext& c) {
      const int n = c.Int(0);
      if (n < 0) { c.Fail("Factorial is not defined for negative integers"); return; }
      // 170! is the last factorial that is finite as a double.
      if (n > 170) { c.Fail("Factorial overflows a double above 170"); return; }
      if (n > 20) c.Warn("Factorial above 20 is not exactly representable as a double");
      double f = 1;
      for (int i = 2; i <= n; ++i) f *= i;
      c.Out(0, Value::Number(f));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Mass Addition"; d.nick = "MassAdd"; d.category = "Maths"; d.subcategory = "Operators";
    d.description = "Sum of a list of numbers, and the running (partial) sums.";
    d.inputs = {In("Input", Kind::Number, Access::List)};
    d.outputs = {Out("Result", Kind::Number), Out("Partial Results", Kind::Number)};
    d.eval = [](EvalContext& c) {
      double sum = 0;
      std::vector<Value> partial;
      for (double x : Numbers(c.List(0))) { sum += x; partial.push_back(Value::Number(sum)); }
      c.Out(0, Value::Number(sum));
      c.OutList(1, partial);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Mass Multiplication"; d.nick = "MassMul"; d.category = "Maths"; d.subcategory = "Operators";
    d.description = "Product of a list of numbers, and the running (partial) products.";
    d.inputs = {In("Input", Kind::Number, Access::List)};
    d.outputs = {Out("Result", Kind::Number), Out("Partial Results", Kind::Number)};
    d.eval = [](EvalContext& c) {
      double prod = 1;
      std::vector<Value> partial;
      for (double x : Numbers(c.List(0))) { prod *= x; partial.push_back(Value::Number(prod)); }
      c.Out(0, Value::Number(prod));
      c.OutList(1, partial);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Square"; d.nick = "Sqr"; d.category = "Maths"; d.subcategory = "Operators";
    d.description = "The square of a number.";
    d.inputs = {In("X", Kind::Number, Access::Item, Value::Number(0))};
    d.outputs = {Out("Result", Kind::Number)};
    d.eval = [](EvalContext& c) { const double x = c.Num(0); c.Out(0, Value::Number(x * x)); };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Pythagorean"; d.nick = "Pyth"; d.category = "Maths"; d.subcategory = "Trig";
    d.description = "The hypotenuse of a right triangle from its two legs, sqrt(A^2 + B^2).";
    d.inputs = {In("A", Kind::Number, Access::Item, Value::Number(0)), In("B", Kind::Number, Access::Item, Value::Number(0))};
    d.outputs = {Out("Hypotenuse", Kind::Number)};
    d.eval = [](EvalContext& c) { c.Out(0, Value::Number(std::hypot(c.Num(0), c.Num(1)))); };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Power Of Two"; d.nick = "2^n"; d.category = "Maths"; d.subcategory = "Polynomials";
    d.description = "Two raised to a power, 2^n.";
    d.inputs = {In("Exponent", Kind::Number, Access::Item, Value::Number(1))};
    d.outputs = {Out("Result", Kind::Number)};
    d.eval = [](EvalContext& c) { c.Out(0, Value::Number(std::exp2(c.Num(0)))); };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Average"; d.nick = "Avg"; d.category = "Maths"; d.subcategory = "Util";
    d.description = "Arithmetic mean of a list of numbers.";
    d.inputs = {In("Input", Kind::Number, Access::List)};
    d.outputs = {Out("Mean", Kind::Number)};
    d.eval = [](EvalContext& c) {
      const std::vector<double> v = Numbers(c.List(0));
      if (v.empty()) { c.Warn("Average of an empty list"); return; }
      double sum = 0;
      for (double x : v) sum += x;
      c.Out(0, Value::Number(sum / static_cast<double>(v.size())));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Round To Multiple"; d.nick = "RoundM"; d.category = "Maths"; d.subcategory = "Util";
    d.description = "Rounds a number to the nearest multiple of another; exact halves round away from zero.";
    d.inputs = {In("Value", Kind::Number, Access::Item, Value::Number(0)), In("Multiple", Kind::Number, Access::Item, Value::Number(1))};
    d.outputs = {Out("Result", Kind::Number)};
    d.eval = [](EvalContext& c) {
      const double v = c.Num(0), m = std::fabs(c.Num(1));
      if (!(m > 0)) { c.Fail("The multiple must be non-zero"); return; }
      c.Out(0, Value::Number(std::round(v / m) * m));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Relative Differences"; d.nick = "RelDiff"; d.category = "Maths"; d.subcategory = "Operators";
    d.description = "Differences between consecutive numbers: out[i] = in[i+1] - in[i].";
    d.inputs = {In("Values", Kind::Number, Access::List)};
    d.outputs = {Out("Differences", Kind::Number)};
    d.eval = [](EvalContext& c) {
      const std::vector<double> v = Numbers(c.List(0));
      std::vector<Value> out;
      for (size_t i = 1; i < v.size(); ++i) out.push_back(Value::Number(v[i] - v[i - 1]));
      c.OutList(0, out);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Fibonacci"; d.nick = "Fib"; d.category = "Maths"; d.subcategory = "Util";
    d.description = "The first Count Fibonacci numbers F(0)=0, F(1)=1, F(n)=F(n-1)+F(n-2). Exact up to F(78).";
    d.inputs = {In("Count", Kind::Integer, Access::Item, Value::Integer(10))};
    d.outputs = {Out("Sequence", Kind::Number)};
    d.eval = [](EvalContext& c) {
      // Clamped like Series' Count: it can come straight from a .dflow file.
      const int n = std::clamp(c.Int(0), 0, 1000);
      if (n > 79) c.Warn("Fibonacci terms above F(78) are not exactly representable as doubles");
      std::vector<Value> out;
      double a = 0, b = 1;
      for (int i = 0; i < n; ++i) { out.push_back(Value::Number(a)); const double t = a + b; a = b; b = t; }
      c.OutList(0, out);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Greatest Common Divisor"; d.nick = "GCD"; d.category = "Maths"; d.subcategory = "Util";
    d.description = "Largest integer dividing both A and B (signs ignored; gcd(0,0) = 0).";
    d.inputs = {In("A", Kind::Integer, Access::Item, Value::Integer(0)), In("B", Kind::Integer, Access::Item, Value::Integer(0))};
    d.outputs = {Out("GCD", Kind::Integer)};
    d.eval = [](EvalContext& c) {
      const long long a = std::llabs(static_cast<long long>(c.Int(0))), b = std::llabs(static_cast<long long>(c.Int(1)));
      c.Out(0, Value::Integer(std::gcd(a, b)));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Least Common Multiple"; d.nick = "LCM"; d.category = "Maths"; d.subcategory = "Util";
    d.description = "Smallest positive integer that both A and B divide (0 when either is 0).";
    d.inputs = {In("A", Kind::Integer, Access::Item, Value::Integer(1)), In("B", Kind::Integer, Access::Item, Value::Integer(1))};
    d.outputs = {Out("LCM", Kind::Integer)};
    d.eval = [](EvalContext& c) {
      const long long a = std::llabs(static_cast<long long>(c.Int(0))), b = std::llabs(static_cast<long long>(c.Int(1)));
      const long long g = std::gcd(a, b);
      // Int() is clamped to int range, so a/g*b is at most 2^62: it cannot overflow long long.
      c.Out(0, Value::Integer(g == 0 ? 0 : a / g * b));
    };
    r.Add(d);
  }
}

void AddRowSets() {
  Registry& r = Registry::Get();
  {
    NodeDef d; d.name = "Cull Nth"; d.nick = "CullN"; d.category = "Sets"; d.subcategory = "List";
    d.description = "Removes every Nth item (the Nth, 2Nth, ... counting from 1, so indices N-1, 2N-1, ...).";
    d.inputs = {In("List", Kind::Any, Access::List), In("N", Kind::Integer, Access::Item, Value::Integer(2))};
    d.outputs = {Out("List", Kind::Any)};
    d.eval = [](EvalContext& c) {
      const std::vector<Value>& l = c.List(0);
      const int n = c.Int(1);
      if (n < 1) { c.Warn("N must be at least 1; the list is unchanged"); c.OutList(0, l); return; }
      std::vector<Value> out;
      for (size_t i = 0; i < l.size(); ++i) if ((i + 1) % static_cast<size_t>(n) != 0) out.push_back(l[i]);
      c.OutList(0, out);
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Split List"; d.nick = "Split"; d.category = "Sets"; d.subcategory = "List";
    d.description = "Splits a list at an index: A holds the items before it, B the item at the index and after.";
    d.inputs = {In("List", Kind::Any, Access::List), In("Index", Kind::Integer, Access::Item, Value::Integer(1))};
    d.outputs = {Out("List A", Kind::Any), Out("List B", Kind::Any)};
    d.eval = [](EvalContext& c) {
      const std::vector<Value>& l = c.List(0);
      const size_t at = static_cast<size_t>(std::clamp(c.Int(1), 0, static_cast<int>(l.size())));
      c.OutList(0, std::vector<Value>(l.begin(), l.begin() + static_cast<std::ptrdiff_t>(at)));
      c.OutList(1, std::vector<Value>(l.begin() + static_cast<std::ptrdiff_t>(at), l.end()));
    };
    r.Add(d);
  }
  {
    NodeDef d; d.name = "Text Distance"; d.nick = "TxtDist"; d.category = "Sets"; d.subcategory = "Text";
    d.description = "Levenshtein edit distance between two texts: the fewest single-character insertions, deletions and substitutions turning A into B.";
    d.inputs = {In("A", Kind::Text, Access::Item, Value::Text("")), In("B", Kind::Text, Access::Item, Value::Text("")),
                In("Case Sensitive", Kind::Boolean, Access::Item, Value::Boolean(true))};
    d.outputs = {Out("Distance", Kind::Integer)};
    d.eval = [](EvalContext& c) {
      std::vector<std::uint32_t> a = CodePoints(c.Text(0)), b = CodePoints(c.Text(1));
      // A text from a file is bounded only by the file; the DP table is |a|*|b| cells, so cap each side.
      if (a.size() > 20000 || b.size() > 20000) { c.Fail("Texts longer than 20000 characters are not compared"); return; }
      if (!c.Bool(2, true)) { for (auto& x : a) x = FoldCase(x); for (auto& x : b) x = FoldCase(x); }
      std::vector<size_t> prev(b.size() + 1), cur(b.size() + 1);
      for (size_t j = 0; j <= b.size(); ++j) prev[j] = j;
      for (size_t i = 1; i <= a.size(); ++i) {
        cur[0] = i;
        for (size_t j = 1; j <= b.size(); ++j) {
          const size_t sub = prev[j - 1] + (a[i - 1] == b[j - 1] ? 0 : 1);
          cur[j] = std::min({prev[j] + 1, cur[j - 1] + 1, sub});
        }
        std::swap(prev, cur);
      }
      c.Out(0, Value::Integer(static_cast<long long>(prev[b.size()])));
    };
    r.Add(d);
  }
}

}  // namespace

void RegisterRowNodes() {
  AddRowMaths();
  AddRowSets();
}

}  // namespace dino8::flow
